I kept flip-flopping on what do do for this week's topic, then thought to myself... "flip-flop!"
That toggles from a state of 0 to 1 and back to 0, which made me think of displaying on and off
state which made me think of cellular automation which made me think, of those have been done to
death, which made me think, what about on a hex grid.

And then I discovered this was a thing.

So here is a hex-grid based cellular automation.

You can put your rulestring in, using the format B#s/S#s which means a new cell will be Born if
surounded by any of the listed values, and an existing cell will Survive if surrounded by any of 
the listed vales.

I've curated a few interesting ones in the "Preset" dropdown (which turns off the random mode)

In AutoRestart mode it will restart options that just die out.

Each will start with just one live cell in the center of the screen to see the pretty hexagonal symmety that develops.

"From 0 to 1 🪜" #WCCChallenge ..... Check out the Birb's Nest Discord https://discord.gg/S8c7qcjw2b

@cartocopia 2025-02-06

*/

let myGrid;

let yCount = 120;  // lower for faster updates, increase for more detail.
let cellHeight;

function setup() {
	createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight));
	background(100);
	pixelDensity(1);
	scale(0.98);
	translate(0.01 * width, 0.01 * height);

	yCount = 2 * floor(yCount / 2) + 1; //odd number

	cellHeight = height / (yCount + 0.5);
	let xCount = 2 * floor(width / (3 * cellHeight / (2 * sqrt(3))) / 2) + 1;

	if (Random_RuleString) {
		RuleString = "B";
		for (let i = 1; i <= 6; i++)
			if (random() < 0.5) RuleString += i;
		RuleString += "/S";
		for (let i = 0; i <= 6; i++)
			if (random() < 0.5) RuleString += i;
	}

	myGrid = new hexgrid(xCount, yCount, RuleString, true);
	myGrid.set(floor(xCount / 2) + 1, floor(yCount / 2), 1);

}

function draw() {
	scale(0.98);
	translate(0.01 * width, 0.01 * height);

	if (myGrid.stopped && AutoRestart) {
		setup();
	}

	myGrid.display(cellHeight);

	if (!Pause) myGrid.update();


}


class hexgrid {
	constructor(_width, _height, _ruleStr, _stop = true) {
		this.width = _width;
		this.height = _height;
		this.stop = _stop;
		this.stopped = false;
		this.cycles = 0;
		this.data = Array(_width * _height).fill(0);
		this.B = [];
		this.S = [];
		this.parseRules(_ruleStr);
	}

	parseRules(_ruleStr = "") {
		if (!_ruleStr.includes("/")) return;

		let rules = _ruleStr.split("/");
		let B = rules[0].split("");
		for (let i = 1; i < B.length; i++) this.B.push(Number(B[i]));
		let S = rules[1].split("");
		for (let i = 1; i < S.length; i++) this.S.push(Number(S[i]));
	}

	set(x, y, value) {
		if (constrain(x, 0, this.width) == x && constrain(y, 0, this.height) == y) {
			let index = x + y * this.width;
			this.data[index] = value;
		}
	}

	get(x, y) {
		if (constrain(x, 0, this.width) == x && constrain(y, 0, this.height) == y) {
			let index = x + y * this.width;
			return this.data[index];
		} else
			return (0);
	}

	tally(x, y) {
		let total = 0;
		if (this.get(x, y - 1) == 1) total += 1;
		if (this.get(x, y + 1) == 1) total += 1;
		if (this.get(x - 1, y) == 1) total += 1;
		if (this.get(x + 1, y) == 1) total += 1;
		if (x % 2 == 1) {
			if (this.get(x - 1, y + 1) == 1) total += 1;
			if (this.get(x + 1, y + 1) == 1) total += 1;
		} else {
			if (this.get(x - 1, y - 1) == 1) total += 1;
			if (this.get(x + 1, y - 1) == 1) total += 1;
		}
		return total;
	}

	hex_coords(x, y, unit) {
		let cX = unit * (2 + 3 * x);
		let cY = unit * sqrt(3) * (1 + 2 * y);
		if (x % 2 == 1) cY += unit * sqrt(3);
		return {
			x: cX,
			y: cY
		}
	}

	update() {
		this.stop = Stop_at_edge;
		if (this.stop && this.cycles >= this.height / 2 - 1) {
			this.stopped = true;
		} else {
			let tempData = Array(this.data.length).fill(0);
			let changed = false;
			for (let y = 0; y < this.height; y++) {
				for (let x = 0; x < this.width; x++) {
					switch (this.get(x, y)) {
						case 0: //empty cell check B rule
							if (this.B.includes(this.tally(x, y))) {
								tempData[x + y * this.width] = 1;
								changed = true;
							}
							break;
						case 1:
							if (this.S.includes(this.tally(x, y))) tempData[x + y * this.width] = 1;
							break;
						default:
							break;
					}
				}
			}
			for (let i = 0; i < tempData.length; i++) this.data[i] = tempData[i];
			this.stopped = !changed;
			this.cycles += 1;
		}
	}

	display(cell_height) {
		let fills = [color("rgba(73,0,73,0.85)"), color("gold")];
		let unit = cell_height / (2 * sqrt(3));
		push();
		noFill();
		stroke("black");
		strokeJoin(ROUND);
		for (let y = 0; y < this.height; y++) {
			for (let x = 0; x < this.width; x++) {
				push();
				fill(fills[this.get(x, y)]);
				let coords = this.hex_coords(x, y, unit);
				translate(coords.x, coords.y)
				beginShape();
				vertex(unit * 2, 0);
				vertex(unit, unit * sqrt(3));
				vertex(-unit, unit * sqrt(3));
				vertex(-unit * 2, 0);
				vertex(-unit, -unit * sqrt(3));
				vertex(unit, -unit * sqrt(3));
				endShape(CLOSE);
				pop();
			}
		}
	}

}

